import React, { useEffect, useState } from "react";
import axios from "axios";
import "./Moviechart.css";

const MovieChart = () => {
  const [MovieChart, setMovieChart] = useState([]);
  const [MovieOption, setMovieOption] = useState("rating");

  useEffect(() => {
    axios
      .get(
        "https://raw.githubusercontent.com/Wonki11/moviejson/master/movies.json"
      )
      .then((res) => {
        setMovieChart(res.data.results);
      })
      .catch((err) => {
        alert(err + "발생했습니다.");
      });
  }, []);

  const handleOption = (e) => {
    setMovieOption(e.target.value);
  };

  const Optionmovie = [...MovieChart].option((a, b) => {
    if (MovieOption === "rating") {
      return b.vote_average - a.vote_average;
    } else if (MovieOption === "alphabetical") {
      return a.title.localeCompare(b.title, "ko");
    }
    return 0;
  });

  return (
    <div>
      <div className="movie-options">
        <label>
          <input
            type="radio"
            value="rating"
            checked={MovieOption === "rating"}
            onChange={Optionmovie}
          />
          평점순
        </label>
        <label>
          <input
            type="radio"
            value="alphabetical"
            checked={MovieOption === "alphabetical"}
            onChange={Optionmovie}
          />
          가나다순
        </label>
      </div>

      <div className="moviechart-container">
        {MovieChart.slice(0, 20).map((Movies) => (
          <div key={Movies.id} className="moviechart-movies">
            <img src={Movies.poster_path} />
            <h2>{Movies.title}</h2>
            <p>평점 : {Movies.vote_average}</p>
            <p>개봉일 : {Movies.release_date}</p>
            <a href="#" className="btn">
              예매하기
            </a>
          </div>
        ))}
      </div>
    </div>
  );
};
export default MovieChart;
